#!/usr/bin/env bash
# usage: scripts/gen-m2-record.sh > residues/residue-30.yaml
# Writes the M2 witness record. Untrusted: `rlt residues` checks every entry.
set -euo pipefail
cat <<'HEAD'
# RLT-003 M2: closed quotient–remainder witnesses modulo 30.
# Generated by scripts/gen-m2-record.sh; checked by `rlt residues residues/residue-30.yaml`.
# Every `written` equation is a kernel-checked theorem; every reading is a
# registered interpretation under RESIDUE-30, never a theorem.

id: residue-30
convention: RESIDUE-30
basis: {text: "The eight representatives may be reported as the result of the registered classification of the 30 entries.", source: RLT-003-M2-APPROVAL}
references: [math29]
quotes:
  - {text: "{1, 7, 11, 13, 17, 19, 23, 29}: 17111317192329", source: NEWS-MATH29}

residues:
HEAD
for r in $(seq 0 29); do
  echo "  - r: $r"
  echo "    witnesses:"
  for p in 2 3 5; do
    q=$((r / p)); s=$((r % p)); k=$((p - 1 - s))
    printf '      - {p: %d, written: "%d = %d × %d + %d", proof: tests/m2/D_%02d_%d.rlt, bound: "%d + (%d + 1) = %d", bound_proof: tests/m2/B_%d_%d.rlt}\n' \
      "$p" "$r" "$p" "$q" "$s" "$r" "$p" "$s" "$k" "$p" "$s" "$p"
  done
done
echo
echo "classes:"
for n in 29 30 31 37 59; do
  q=$((n / 30)); r=$((n % 30)); k=$((29 - r))
  printf '  - {n: %d, written: "%d = 30 × %d + %d", proof: tests/m2/W_%d.rlt, bound: "%d + (%d + 1) = 30", bound_proof: tests/m2/C_%d.rlt}\n' \
    "$n" "$n" "$q" "$r" "$n" "$r" "$k" "$r"
done
cat <<'TAIL'

example: {written: "(1 + 1) × 3 × 5 = 30", proof: tests/m2/E_math29.rlt}
tally:
  written: "1 + 1 + 1 + 1 + 1 + 1 + 1 + 1 = 8"
  proof: tests/m2/T_eight.rlt
  binds: [1, 7, 11, 13, 17, 19, 23, 29]
TAIL
